/**
 * Canonical TypeScript shape of shared/handy-speech-catalog.json.
 *
 * One declaration for both sides of the app: the backend loader and the
 * desktop UI import these types type-only, so there is no runtime coupling.
 * The JSON snapshot is generated by scripts/sync_handy_speech_catalog.mjs and
 * pinned to Handy (MIT, © CJ Pais) and @handy-computer/models@0.2.3 (MIT).
 */

export type SpeechModelRole = 'asr' | 'langid' | 'vad' | 'diarize';

export type SpeechMachineTier = 'accelerated' | 'cpu';

export interface SpeechModelCapabilities {
    readonly streaming: boolean;
    readonly translate: boolean;
    readonly languageDetection: boolean;
    readonly timestamps: boolean;
}

/** The one file Quenderin downloads: the catalog's default quant for the model. */
export interface SpeechModelFile {
    readonly quant: string;
    readonly filename: string;
    /** Exact size in bytes. */
    readonly size: number;
    /** Lowercase SHA-256 of the exact bytes at `revision`. */
    readonly sha256: string;
    /** https://huggingface.co/{repository}/resolve/{revision}/{filename} */
    readonly url: string;
}

/** A curated ASR entry from Handy's catalog, verbatim plus the chosen file. */
export interface HandySpeechModel {
    readonly id: string;
    readonly name: string;
    readonly description: string;
    readonly repository: string;
    readonly revision: string;
    readonly previousRevisions: readonly string[];
    /** SPDX id for the model weights (not the Handy code license). */
    readonly license: string;
    readonly family: string;
    readonly parameters: string | null;
    readonly languages: readonly string[];
    readonly capabilities: SpeechModelCapabilities;
    readonly quant: string;
    readonly role: 'asr';
    readonly curated: true;
    /** Oldest transcribe.cpp release publishing these exact files. */
    readonly minEngine: string;
    readonly file: SpeechModelFile;
}

export interface SpeechAccuracyCell {
    /** Word or character error, in percent. */
    readonly error: number;
    /** Lower bound of the 95% confidence interval, when measured. */
    readonly ciLower?: number;
}

export interface SpeechModelResults {
    /** Keyed by language identity (Handy's own spelling, e.g. "en"). */
    readonly accuracy: Readonly<Record<string, SpeechAccuracyCell>>;
    /** Real-time factor on each benchmark tier. */
    readonly performance: Readonly<Partial<Record<SpeechMachineTier, number>>>;
}

/** Handy's recommendation method; the UI's grading/speed display only needs the wait fields. */
export interface SpeechMethodology {
    readonly dictationSeconds: number;
    readonly freeWaitSeconds: number;
    readonly waitWeight: number;
    readonly overallMaxWaitSeconds: number;
    readonly maxLanguageErrorPercent: number;
    readonly noteMinErrorPercent: number;
    readonly experimentalMaxErrorPercent: number;
    readonly fastCpuMaxWaitSeconds: number;
    readonly accurateMaxWaitSeconds: number;
}

export interface SpeechBenchmarks {
    readonly quant: string;
    readonly accuracy: {
        readonly dataset: string;
        readonly split: string;
    };
    readonly speed: {
        readonly accelerated: {
            readonly machine: string;
            readonly backend: string;
        };
        readonly cpu: {
            readonly machine: string;
            readonly backend: string;
        };
    };
}

export interface HandySpeechCatalogSource {
    readonly handy: {
        readonly name: string;
        readonly repository: string;
        readonly commit: string;
        readonly catalogPath: string;
        readonly license: string;
        readonly copyright: string;
    };
    readonly package: {
        readonly name: string;
        readonly version: string;
        readonly repository: string;
        readonly catalogPath: string;
        readonly license: string;
    };
    readonly generator: string;
}

/** Shape of shared/handy-speech-catalog.json. */
export interface HandySpeechCatalog {
    readonly schema: 1;
    readonly source: HandySpeechCatalogSource;
    /** The transcribe.cpp release the facts and benchmarks come from. */
    readonly transcribeCpp: string;
    readonly languageDetector: string;
    readonly methodology: SpeechMethodology;
    readonly benchmarks: SpeechBenchmarks;
    /** Exactly the models with role="asr" && curated=true. */
    readonly models: readonly HandySpeechModel[];
    /** Benchmark results keyed by model id, restricted to the bundled models. */
    readonly results: Readonly<Record<string, SpeechModelResults>>;
}
